-- Customer experience analytics wiki section (top-level sibling of "Data modeling").
-- Idempotent: pages upsert by slug; parent wiring and wikilinks are join-based and
-- safe to re-run. Cross-section wikilinks resolve only once the target pages exist,
-- so re-run all five domain seeds after the first pass to wire cross-links.
-- Mirrors what was seeded to the live DB via the Supabase MCP (2026-06).

insert into pages (title, slug, kind, content, visibility) values ('Customer experience analytics', 'cx-analytics', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Customer experience analytics covers what happens after the sale: support, customer success, and the voice of the customer, all pointed at one outcome, whether customers stay and grow. It's the retention side of the revenue story, the mirror image of "},{"type":"wikilink","attrs":{"title":"Sales analytics"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Three overlapping practices live here. Support analytics measures the help desk. Customer success analytics measures whether customers reach value and renew. Voice of customer captures what they actually think. The thread tying them together is churn: every metric in this section is, in the end, a leading indicator of whether revenue leaves."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Theory"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Support — ","marks":[{"type":"bold"}]},{"type":"text","text":"ticket volume, response and resolution time, deflection, the operational metrics."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Satisfaction and success — ","marks":[{"type":"bold"}]},{"type":"text","text":"CSAT, NPS, CES, customer success analytics, and health scores."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Retention — ","marks":[{"type":"bold"}]},{"type":"text","text":"churn and retention, logo versus revenue, the link to the dollars."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Practice"}]},{"type":"paragraph","content":[{"type":"text","text":"Health score as a modeled feature, the support-to-product feedback loop, survey pitfalls, the CX data stack, and churn modeling in dbt."}]},{"type":"paragraph","content":[{"type":"text","text":"The most valuable thing CX analytics produces is early warning. A health score that flags a churn risk 60 days out is worth more than a perfect post-mortem on why a customer left."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Support analytics"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"CX analytics practice"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"CX voices and canon"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Support analytics', 'support-analytics', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Support analytics measures the help desk as an operation: how much work comes in, how fast it gets handled, and how well. It's the most operational corner of CX, and its metrics are mostly about flow."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Volume and backlog — ","marks":[{"type":"bold"}]},{"type":"text","text":"tickets in, tickets open, the queue. The workload picture."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"First response time — ","marks":[{"type":"bold"}]},{"type":"text","text":"how long until a human replies. Strongly correlated with satisfaction; under an hour is a common target."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Resolution time and first-contact resolution — ","marks":[{"type":"bold"}]},{"type":"text","text":"how long to actually solve it, and the share solved in one touch. FCR around 70% is a typical benchmark (directional)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deflection and resolution rate — ","marks":[{"type":"bold"}]},{"type":"text","text":"tickets handled by self-serve or automation before a human. The field is shifting from measuring deflection to measuring actual resolution."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Modeled well, support is a "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" problem (one row per ticket, plus events for state transitions) that lets you compute cycle time the same way "},{"type":"wikilink","attrs":{"title":"Throughput, cycle time and capacity"}},{"type":"text","text":" does for ops. The trap is treating volume as bad: more tickets can mean more usage, not more failure, so always read support metrics next to product usage, not alone."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Satisfaction metrics (CSAT, NPS, CES)"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Throughput, cycle time and capacity"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Grain"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Satisfaction metrics (CSAT, NPS, CES)', 'satisfaction-metrics', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three survey metrics dominate CX, and they measure genuinely different things. Using the wrong one for the question is the most common mistake."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CSAT — ","marks":[{"type":"bold"}]},{"type":"text","text":"satisfaction with a specific interaction, asked right after it. Transactional, fresh, narrow."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"NPS — ","marks":[{"type":"bold"}]},{"type":"text","text":"likelihood to recommend, a relational measure of overall loyalty. Created by Reichheld in 2003. Broad, slow-moving, brand-level."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CES — ","marks":[{"type":"bold"}]},{"type":"text","text":"how much effort it took to get something done. Predicts loyalty well, especially for support, on the theory that reducing friction beats delighting."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"CSAT and CES tell you how individual interactions are going; NPS tells you whether they add up to loyalty. Strong programs use all three for their different jobs. For analytics the important part is that these are survey data with all the bias that implies, so model them with their methodology attached and never treat a satisfaction score as ground truth about behavior. The honest caveats live in "},{"type":"wikilink","attrs":{"title":"Survey methodology pitfalls"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Support analytics"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Voice of customer"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Survey methodology pitfalls"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Customer success analytics', 'customer-success-analytics', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Customer success analytics measures whether customers reach the value they bought, and whether that turns into renewal and expansion. Where support is reactive, success is proactive: spot the account drifting before it churns, and the account thriving before it expands."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"What it tracks"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Adoption and usage — ","marks":[{"type":"bold"}]},{"type":"text","text":"are they actually using the thing, at what depth, across how many users. The clearest leading signal."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Onboarding and time to value — ","marks":[{"type":"bold"}]},{"type":"text","text":"how fast a new customer reaches the first real outcome. Slow onboarding predicts churn early."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Renewal and expansion signals — ","marks":[{"type":"bold"}]},{"type":"text","text":"the trajectory of an account, the input to net revenue retention and to land and expand."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This is the renewal-side counterpart to "},{"type":"wikilink","attrs":{"title":"Land and expand"}},{"type":"text","text":" on the sales side: same accounts, same trajectory, viewed from retention instead of acquisition. The analytics job is to join usage, support, and contract data into one account view, which is the foundation for the "},{"type":"wikilink","attrs":{"title":"Customer health scores"}},{"type":"text","text":" everything in this section builds toward."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Customer health scores"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Land and expand"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Churn and retention"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Customer health scores', 'customer-health-scores', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A customer health score is a single composite number that predicts whether an account will renew, churn, or grow. It's the flagship output of CX analytics, and done right it buys you time: automated scores flag churn risk weeks earlier than a CSM's gut, often around 60 days out versus a handful (directional, vendor data)."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"What goes into one"}]},{"type":"paragraph","content":[{"type":"text","text":"A weighted blend of leading indicators: product usage and adoption depth (the heaviest weight, often around 40%), engagement quality, support experience, and business fit or contract signals. The exact weights are a modeling choice, and the discipline is to use leading indicators that let you intervene, not lagging ones that just confirm the loss."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The signals that actually predict"}]},{"type":"paragraph","content":[{"type":"text","text":"Integration usage (how embedded you are), the number of power users (accounts with several rarely churn, accounts with none often do), and direction of travel (an annual-to-monthly downgrade is a warning, a monthly-to-annual upgrade is expansion coming)."}]},{"type":"paragraph","content":[{"type":"text","text":"A health score is not a dashboard tile, it's a modeled feature, and that's the whole point of "},{"type":"wikilink","attrs":{"title":"Health score as a modeled feature"}},{"type":"text","text":". Build it in the warehouse from governed inputs, version it, and it becomes something every team and every model can trust."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Customer success analytics"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Health score as a modeled feature"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Churn and retention"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Churn and retention', 'churn-and-retention', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Churn is customers or revenue leaving; retention is what stays. It's the outcome every other CX metric is a leading indicator of, and the place where customer experience meets the P&L."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Logo churn — ","marks":[{"type":"bold"}]},{"type":"text","text":"customers lost ÷ customers at the start. Counts heads."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Revenue churn — ","marks":[{"type":"bold"}]},{"type":"text","text":"revenue lost to cancels and downgrades ÷ starting revenue. Counts dollars."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Gross versus net — ","marks":[{"type":"bold"}]},{"type":"text","text":"gross retention ignores expansion and caps at 100%; net retention adds expansion and can exceed it."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Logo and revenue churn diverge hard when account sizes vary: losing ten tiny accounts and ten enterprise accounts is the same logo churn and a wildly different revenue hit. Track both, and lead with revenue churn for health. Remember too that some churn is involuntary, a failed payment, not a decision, which is the cheapest churn to win back and belongs to "},{"type":"wikilink","attrs":{"title":"Dunning and involuntary churn"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"This is the same metric finance reports as "},{"type":"wikilink","attrs":{"title":"Revenue retention (GRR and NRR)"}},{"type":"text","text":"; CX owns the leading indicators, finance owns the dollars. They should reconcile to the same number, which is an argument for one shared definition."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Revenue retention (GRR and NRR)"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Dunning and involuntary churn"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Churn modeling in dbt"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Voice of customer', 'voice-of-customer', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Voice of customer is the qualitative side: what customers say, in surveys, support tickets, reviews, interviews, and sales calls. It's the texture the metrics miss, the why behind a falling CSAT or a stalled account."}]},{"type":"paragraph","content":[{"type":"text","text":"The analytics challenge is that it's unstructured text, and the temptation is to either ignore it or drown in it. The middle path is to structure it: tag tickets and survey verbatims by theme, quantify how often each theme shows up, and trend it. A health score tells you an account is sliding; the voice data tells you it's because a feature they need keeps breaking."}]},{"type":"paragraph","content":[{"type":"text","text":"This is increasingly where language models earn their place in the stack, classifying and summarizing feedback at volume, but the same governance rules apply: the categories have to be defined and stable, or the trend is noise. The payoff is a feedback loop into the product, which is the subject of "},{"type":"wikilink","attrs":{"title":"The support to product feedback loop"}},{"type":"text","text":". Treat qualitative data as data, with grain and definitions, not as anecdote."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Satisfaction metrics (CSAT, NPS, CES)"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The support to product feedback loop"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Survey methodology pitfalls"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('CX voices and canon', 'cx-voices-and-canon', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Customer success and CX have a clearer canon than marketing or sales, anchored by a few books and a strong community. Who to read and why."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Customer success"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nick Mehta (Gainsight) — ","marks":[{"type":"bold"}]},{"type":"text","text":"Customer Success, the book that named and shaped the discipline, plus the Gainsight benchmark research."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Lincoln Murphy — ","marks":[{"type":"bold"}]},{"type":"text","text":"customer success and the activation, time-to-value, and trial frameworks that connect CS back to growth."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The metrics"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fred Reichheld (Bain) — ","marks":[{"type":"bold"}]},{"type":"text","text":"the Net Promoter Score, from the 2003 HBR article, and the loyalty research behind it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The CES origin — ","marks":[{"type":"bold"}]},{"type":"text","text":"the 2010 HBR Stop Trying to Delight Your Customers, the effort-over-delight argument."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Communities and tools as reference"}]},{"type":"paragraph","content":[{"type":"text","text":"The customer success community (CS leadership networks, Gain Grow Retain), and the platform vendors as publishers: Gainsight, Catalyst, Vitally, Totango on health scoring and retention."}]},{"type":"paragraph","content":[{"type":"text","text":"The churn and retention benchmarks here are vendor-sourced and directional. Bain's retention-to-profit research is the most-cited durable finding: a small retention gain compounds into a large profit gain.","marks":[{"type":"italic"}]}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('CX analytics practice', 'cx-analytics-practice', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The theory is the metrics. This hub is the build, and it centers on one ambitious output: a health score you can trust, made from joined-up data across support, product, and revenue."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Health score as a modeled feature, not a dashboard tile."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The support-to-product feedback loop."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Survey methodology pitfalls, the honest caveats."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The CX data stack and churn modeling in dbt."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Customer experience analytics"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Health score as a modeled feature"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Health score as a modeled feature', 'health-score-as-a-modeled-feature', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A health score earns its keep only when it's a modeled feature in the warehouse, not a formula buried in a CS tool. As a model it's testable, versioned, explainable, and reusable by every team and every downstream model. As a black box in a SaaS tool it's a number people stop trusting the first time it's wrong."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Building it"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Join the inputs — ","marks":[{"type":"bold"}]},{"type":"text","text":"usage, support, and contract data into one account-grain table. The join is the hard part and the valuable part."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Define the components — ","marks":[{"type":"bold"}]},{"type":"text","text":"each input (adoption, engagement, support, fit) as its own measured, tested column."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Weight and combine — ","marks":[{"type":"bold"}]},{"type":"text","text":"the score as an explicit, version-controlled combination, so a weight change is a reviewable diff, not a silent edit."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This is the CX expression of taro's whole thesis: define the thing once, in code, with a clear "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" and governed inputs, and it becomes trustworthy for humans and machines alike. A health score that's a real model can feed the CRM via reverse ETL, trigger CS workflows, and train a churn predictor, all from one definition. See "},{"type":"wikilink","attrs":{"title":"Churn modeling in dbt"}},{"type":"text","text":" for the predictive extension."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Customer health scores"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Churn modeling in dbt"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Grain"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('The support to product feedback loop', 'support-to-product-feedback-loop', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Support is the richest source of product truth in the company, and most of it evaporates because the data never makes it back to the people who build the product. Closing that loop is a high-leverage, underrated piece of CX analytics."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"How to close it"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Categorize tickets — ","marks":[{"type":"bold"}]},{"type":"text","text":"tag every ticket by product area and issue type, with a stable taxonomy, so volume by category is a real signal."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Join to usage and revenue — ","marks":[{"type":"bold"}]},{"type":"text","text":"connect ticket themes to which features, which accounts, and how much revenue, so the loudest pain is weighed by its actual cost."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Route it to the product — ","marks":[{"type":"bold"}]},{"type":"text","text":"trend the categories and surface them where product decisions get made, not in a support dashboard nobody on the product team opens."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Done well this turns support from a cost center into the product's early-warning system: the feature that generates the most tickets among your highest-value accounts is a roadmap input you can defend with data. It's the same entity-first modeling idea as "},{"type":"wikilink","attrs":{"title":"Taxonomy and ontology"}},{"type":"text","text":", applied to support: model the issues as structured objects and the feedback becomes analyzable instead of anecdotal."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Voice of customer"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Taxonomy and ontology"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Customer success analytics"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Survey methodology pitfalls', 'survey-methodology-pitfalls', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Survey metrics, CSAT, NPS, CES, feel like hard data and aren't. They're self-reported, sampled, and biased in predictable ways, and an analytics engineer who treats them as ground truth will build confident, wrong conclusions."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The pitfalls that recur"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Response bias — ","marks":[{"type":"bold"}]},{"type":"text","text":"the people who answer are the very happy and the very angry. The silent middle is missing, so the score is bimodal in disguise."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Timing and selection — ","marks":[{"type":"bold"}]},{"type":"text","text":"ask right after a good interaction and you flatter yourself. Who gets surveyed, and when, shapes the result more than the result shapes reality."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tiny samples — ","marks":[{"type":"bold"}]},{"type":"text","text":"a B2B account might return three responses. An NPS swing on three responses is noise wearing a number."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Gaming — ","marks":[{"type":"bold"}]},{"type":"text","text":"when a score drives compensation, people ask for good scores and pre-screen who gets surveyed, and the metric quietly stops measuring satisfaction."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The discipline is to keep the methodology attached to the number: sample size, timing, response rate, all modeled alongside the score, so a reader knows how much weight it carries. This is "},{"type":"wikilink","attrs":{"title":"Testing & data quality"}},{"type":"text","text":" for survey data, and it's why health scores lean on behavioral signals over survey signals where they can. Behavior is harder to fake than a survey answer."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Satisfaction metrics (CSAT, NPS, CES)"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Testing & data quality"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Customer health scores"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('The CX data stack', 'the-cx-data-stack', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The systems CX analytics pulls from, sorted by what they hold:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Support platforms — ","marks":[{"type":"bold"}]},{"type":"text","text":"Zendesk, Intercom, Salesforce Service Cloud. Tickets, conversations, response times."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Customer success platforms — ","marks":[{"type":"bold"}]},{"type":"text","text":"Gainsight, Catalyst, Vitally, Totango. Account health, playbooks, renewal tracking, often with their own health-score engine."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Survey tools — ","marks":[{"type":"bold"}]},{"type":"text","text":"the CSAT, NPS, and CES collection, sometimes inside the support or CS platform, sometimes standalone."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"These land in the warehouse the usual way: managed connectors (the Fivetran Zendesk and Intercom packages) extract and load, dbt models them into ticket, conversation, and account marts. The strategic choice is whether the health score lives in the CS platform's black box or in your warehouse as a "},{"type":"wikilink","attrs":{"title":"Health score as a modeled feature"}},{"type":"text","text":". The warehouse version wins for the same reasons it wins everywhere: one definition, testable, joinable to product and revenue data the CS tool can't see."}]},{"type":"paragraph","content":[{"type":"text","text":"The CS platform is then best treated as an interface, fed by reverse ETL from the warehouse, the same pattern as the "},{"type":"wikilink","attrs":{"title":"CRM and warehouse sync"}},{"type":"text","text":" on the sales side."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Health score as a modeled feature"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"CRM and warehouse sync"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Customer health scores"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Churn modeling in dbt', 'churn-modeling-in-dbt', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Churn modeling is where CX analytics gets predictive: not just reporting who left, but estimating who will. It builds directly on the health-score foundation, and it's a clean example of the analytics-to-ML handoff."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The build"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Define churn precisely — ","marks":[{"type":"bold"}]},{"type":"text","text":"voluntary versus involuntary, logo versus revenue, and the exact window. A fuzzy label trains a useless model."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Engineer features — ","marks":[{"type":"bold"}]},{"type":"text","text":"the health-score inputs, usage trends, support signals, contract trajectory, at an account-month grain, in dbt where they're tested and versioned."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hand off to a model — ","marks":[{"type":"bold"}]},{"type":"text","text":"the feature table feeds a churn classifier; the prediction comes back as another column the warehouse owns."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Most of the value is in the feature engineering, which is squarely analytics-engineering work, not data science: clean, well-grained, governed features are what make a churn model trustworthy, and they're reusable far beyond it. This is "},{"type":"wikilink","attrs":{"title":"ML / AI integration"}},{"type":"text","text":" with a concrete target, and it closes the CX loop: the same modeled inputs power the health score, the prediction, and the intervention."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Health score as a modeled feature"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"ML / AI integration"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Churn and retention"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
update pages c set parent_id = pa.id from pages pa where pa.slug = 'cx-analytics' and c.slug in ('support-analytics','satisfaction-metrics','customer-success-analytics','customer-health-scores','churn-and-retention','voice-of-customer','cx-voices-and-canon','cx-analytics-practice');
update pages c set parent_id = pa.id from pages pa where pa.slug = 'cx-analytics-practice' and c.slug in ('health-score-as-a-modeled-feature','support-to-product-feedback-loop','survey-methodology-pitfalls','the-cx-data-stack','churn-modeling-in-dbt');
